WebdriverIO (8 and 9) helper for this template — in a WebdriverIO suite, use it as written:
Facts:
  • hidden copies: each FAQ item exists twice; only the displayed items are the page's FAQ
  • no attribute carries the question — an item is found by its exact question text
  • an open question has the class "expanded" (the first is open on load)
```js
const QUESTION = 'p.pricing-redesign__faqs-section__faq-item__question';

async function faqItems() {
  const items = [];
  for (const item of await $$('div.pricing-redesign__faqs-section__faq-item')) {
    if (await item.isDisplayed()) items.push(item);
  }
  return items;
}

async function faqItem(question) {
  for (const item of await faqItems()) {
    if ((await item.$(QUESTION).getText()).trim() === question) return item;
  }
  throw new Error(`No FAQ question "${question}"`);
}

const faqQuestion = async (question) => (await faqItem(question)).$(QUESTION);
const faqAnswer = async (question) => (await faqItem(question)).$('div.pricing-redesign__faqs-section__faq-item__answer-wrapper');
const isExpanded = async (question) => (await (await faqQuestion(question)).getAttribute('class')).split(/\s+/).includes('expanded');
```
